1	// Shared setup for the app.js tests on the fake page.
2	import { flush, loadApp } from './fake-dom.mjs';
3	
4	export const NO_REPLY = 'Could not reach the server.';
5	export const FAILED = 'Request failed.';
6	export const ROOM_NAMES = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
7	
8	export const roomsCall = (page) => page.fetches.find((f) => f.url === '/api/rooms');
9	export const errorText = (page) => page.el('error').textContent;
10	export const listItems = (page) => page.el('booking-list').childNodes;
