12	/** Loads the app, answers the rooms fetch and the first list fetch, and lets them settle. */
13	export async function boot({ rooms = ROOM_NAMES, bookings = [] } = {}) {
14	  const page = loadApp();
15	  roomsCall(page).reply(200, { rooms });
16	  page.listFetches()[0].reply(200, { bookings });
17	  await flush();
18	  return page;
19	}
