1	// Startup rules: PORT checks, DATA_FILE resolution and strict data-file reading.
2	import assert from 'node:assert/strict';
3	import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
4	import { connect } from 'node:net';
5	import { join } from 'node:path';
6	import { after, before, describe, test } from 'node:test';
7	import {
8	  LISTEN_RE, ROOT, booking, delay, exists, expectError, getBookings, isPortFree, makeTmpDir,
9	  MSG, occupyPort, postBooking, request, runToExit, spawnServer, withServer, writeStore,
10	} from './helpers/server.mjs';
11	
12	const MAX_POLLS = 500;
13	// Built from code points so no invisible or look-alike characters sit in the source.
14	const BOM = String.fromCodePoint(0xfeff);
15	const ARABIC_INDIC_80 = String.fromCodePoint(0x0668, 0x0660);
16	const FULLWIDTH_80 = String.fromCodePoint(0xff18, 0xff10);
17	const dataError = (name) => `cannot read data file ${name}\n`;
18	
19	/** Asserts a clean one-line startup failure; `stderr` (optional) is the exact expected text. */
20	function assertFailure(r, stderr) {
21	  assert.strictEqual(r.code, 1);
22	  assert.strictEqual(r.stdout, '');
23	  assert.match(r.stderr, /^[^\n]+\n$/);
24	  assert.ok(!r.stderr.includes('\n    at '), 'stderr has a stack trace');
25	  if (stderr !== undefined) assert.strictEqual(r.stderr, stderr);
26	}
27	
28	/** A free port number (bound and released). */
29	async function freePort() {
30	  const blocker = await occupyPort();
31	  await blocker.close();
32	  return blocker.port;
33	}
34	
35	/** Starts on a fixed PORT (unset when undefined) and returns stdout after listening (max ~5 s). */
36	async function listenLine(cwd, port, dataFile) {
37	  const handle = spawnServer({ cwd, env: { PORT: port, DATA_FILE: dataFile } });
38	  try {
39	    for (let i = 0; i < MAX_POLLS && !handle.stdout().includes('\n'); i++) {
40	      if (handle.child.exitCode !== null) break;
41	      await delay(10);
42	    }
43	    return handle.stdout();
44	  } finally {
45	    handle.child.kill();
46	    await handle.exited;
47	  }
48	}
