50	let tmp;
51	const tmpPath = (...parts) => join(tmp, ...parts);
52	before(async () => {
53	  tmp = await makeTmpDir();
54	});
55	after(() => rm(tmp, { recursive: true, force: true }));
56	
57	/** Fresh empty sub-directory of tmp for one test. */
58	let counter = 0;
59	async function freshDir() {
60	  const dir = tmpPath(`case${counter++}`);
61	  await mkdir(dir);
62	  return dir;
63	}
