65	describe('PORT=0', () => {
66	  test('prints exactly one listening line and nothing else', async () => {
67	    const dir = await freshDir();
68	    await withServer({ cwd: dir, env: { DATA_FILE: tmpPath('none.json') } }, async (s) => {
69	      const m = LISTEN_RE.exec(s.stdout());
70	      assert.ok(m, 'listening line');
71	      assert.ok(s.port > 0);
72	      assert.strictEqual(Number(m[1]), s.port);
73	      assert.strictEqual((await request(s.port, { path: '/api/rooms' })).status, 200);
74	      assert.strictEqual((await request(s.port, { path: '/nope' })).status, 404);
75	      assert.strictEqual((await postBooking(s.port, '{bad')).status, 400);
76	      assert.strictEqual((await request(s.port, { method: 'PUT', path: '/api/rooms' })).status, 405);
77	      const line = s.stdout();
78	      assert.strictEqual(line, `listening on http://127.0.0.1:${s.port}\n`);
79	      assert.strictEqual(s.stderr(), '');
80	    });
81	  });
82	});
