84	describe('default port 3000', () => {
85	  for (const [label, port] of [['unset', undefined], ['empty', '']]) {
86	    test(`PORT ${label}`, async (t) => {
87	      if (!(await isPortFree(3000))) return t.skip('port 3000 busy');
88	      const dir = await freshDir();
89	      const out = await listenLine(dir, port, tmpPath('none.json'));
90	      assert.strictEqual(out, 'listening on http://127.0.0.1:3000\n');
