119	describe('bad PORT is checked before the data file', () => {
120	  const bad = ['abc', '-1', '65536', '100000', ' 80', '80 ', '1e3', '0x50', '+80', '8 0', '8.0',
121	    ARABIC_INDIC_80, FULLWIDTH_80, '99999999999999999999', '80\n'];
