157	describe('no listening on data failure', () => {
158	  test('nobody can connect while the server dies', async () => {
159	    const port = await freePort();
160	    const dir = await freshDir();
161	    await writeFile(join(dir, 'empty.json'), '');
162	    const handle = spawnServer({ cwd: dir, env: { PORT: String(port), DATA_FILE: 'empty.json' } });
163	    let done = false;
164	    let connected = false;
165	    handle.exited.then(() => (done = true));
166	    for (let i = 0; i < MAX_POLLS && !done; i++) {
167	      await new Promise((resolve) => {
168	        const s = connect(port, '127.0.0.1');
169	        s.once('connect', () => { connected = true; s.destroy(); resolve(); });
170	        s.once('error', () => resolve());
171	      });
172	      await delay(10);
173	    }
174	    if (!done) {
175	      handle.child.kill('SIGKILL');
176	      await handle.exited;
177	      assert.fail(`server still running after ${MAX_POLLS} connect attempts`);
178	    }
179	    const { code } = await handle.exited;
180	    assert.strictEqual(connected, false);
181	    assert.strictEqual(code, 1);
182	    assert.strictEqual(handle.stdout(), '');
183	    assert.strictEqual(handle.stderr(), dataError('empty.json'));
184	  });
185	});
