187	describe('DATA_FILE default and relative resolution', () => {
188	  const seeded = { id: 1, ...booking() };
189	  const next = booking({ start: '10:00', end: '11:00' });
190	
191	  /** Seeds `file` (relative to a fresh dir), runs server with env, checks load and save. */
192	  async function loadAndSave(file, env, savedName) {
193	    const dir = await freshDir();
194	    const target = join(dir, file);
195	    await mkdir(join(target, '..'), { recursive: true });
196	    await writeStore(target, [seeded], 5);
197	    await withServer({ cwd: dir, env }, async (s) => {
198	      assert.deepStrictEqual(await getBookings(s.port), [seeded]);
199	      const res = await postBooking(s.port, next);
200	      assert.strictEqual(res.status, 201);
201	      assert.strictEqual(res.json.id, 5);
202	    });
203	    const saved = JSON.parse(await readFile(join(dir, savedName ?? file), 'utf8'));
204	    assert.deepStrictEqual(saved.bookings.map((b) => b.id), [1, 5]);
205	    assert.strictEqual(saved.nextId, 6);
