1	// A minimal fake browser for public/app.js: only the APIs the spec allows.
2	// Any other member the script touches is recorded in `page.violations` (and throws).
3	import { readFileSync } from 'node:fs';
4	import { join } from 'node:path';
5	import vm from 'node:vm';
6	import { ROOT } from './server.mjs';
7	
8	export const APP_PATH = join(ROOT, 'public', 'app.js');
9	
10	const ELEMENT_MEMBERS = new Set([
11	  'textContent', 'value', 'type', 'disabled', 'append', 'replaceChildren', 'addEventListener',
12	]);
13	const PAGE_ELEMENTS = [
14	  ['booking-form', 'form'], ['room', 'select'], ['title', 'input', 'text'], ['date', 'input', 'date'],
15	  ['start', 'input', 'time'], ['end', 'input', 'time'], ['book', 'button', 'submit'],
16	  ['filter-date', 'input', 'date'], ['show-all', 'button', 'button'], ['booking-list', 'ul'],
17	  ['error', 'p'],
18	];
19	
20	export class TextNode {
21	  constructor(data) {
22	    this.nodeType = 3;
23	    this.data = String(data);
24	  }
25	}
26	
27	/** Test-side element. The script only ever sees `el.proxy`. */
28	export class FakeElement {
29	  constructor(page, tag, { id = null, type = '' } = {}) {
30	    this.page = page;
31	    this.tag = tag;
32	    this.id = id;
33	    this.type = type;
34	    this.disabled = false;
35	    this.childNodes = [];
36	    this.listeners = {};
37	    this.storedValue = '';
38	    this.proxy = page.wrap(this, this.label(), ELEMENT_MEMBERS);
39	  }
40	
41	  label() {
42	    return this.id ? `#${this.id}` : `<${this.tag}>`;
43	  }
44	
45	  get value() {
46	    if (this.tag === 'select' && this.storedValue === '' && this.childNodes.length > 0) {
47	      return this.childNodes[0].value;
48	    }
49	    return this.storedValue;
50	  }
51	
52	  set value(v) {
53	    this.storedValue = String(v);
54	  }
55	
56	  get textContent() {
57	    return this.childNodes.map((n) => (n instanceof TextNode ? n.data : n.textContent)).join('');
58	  }
59	
60	  set textContent(v) {
61	    const text = String(v);
62	    this.childNodes = text === '' ? [] : [new TextNode(text)];
63	  }
64	
65	  get children() {
66	    return this.childNodes.filter((n) => n instanceof FakeElement);
67	  }
68	
69	  toNodes(items) {
70	    return items.map((item) => {
71	      if (typeof item === 'string') return new TextNode(item);
72	      const el = this.page.unwrap(item);
73	      if (!el) throw new TypeError('append/replaceChildren got a non-node');
74	      return el;
75	    });
76	  }
77	
78	  append(...items) {
79	    this.childNodes = [...this.childNodes, ...this.toNodes(items)];
80	  }
81	
82	  replaceChildren(...items) {
83	    this.childNodes = this.toNodes(items);
84	  }
85	
86	  addEventListener(type, fn) {
87	    this.listeners[type] = [...(this.listeners[type] ?? []), fn];
88	  }
89	
90	  /** Test-side: fire an event; resolves to the event (see `defaultPrevented`). */
91	  dispatch(type) {
92	    const event = { type, defaultPrevented: false, preventDefaultCalls: 0 };
93	    const exposed = this.page.wrap(
94	      { preventDefault: () => { event.defaultPrevented = true; event.preventDefaultCalls += 1; } },
95	      `${type} event`, new Set(['preventDefault']),
96	    );
97	    for (const fn of this.listeners[type] ?? []) fn.call(this.proxy, exposed);
98	    return event;
99	  }
100	
101	  /**
102	   * Test-side click. Unlike a browser it reaches the listeners even when the
103	   * button is disabled, so the script's own "disabled sends nothing" guard is tested.
104	   */
105	  click() {
106	    return this.dispatch('click');
107	  }
108	}
109	
110	function makeResponse(page, status, json) {
111	  return page.wrap({ status, json }, 'response', new Set(['status', 'json']));
112	}
113	
114	/** One recorded fetch call, settled by the test. */
115	class FetchCall {
116	  constructor(page, url, options) {
117	    this.page = page;
118	    this.url = url;
119	    this.options = options;
120	    this.method = options?.method ?? 'GET';
121	    this.promise = new Promise((resolve, reject) => {
122	      this.resolveFetch = resolve;
123	      this.rejectFetch = reject;
124	    });
125	  }
126	
127	  /** Reply with a status and a JSON-able body (json() resolves to a copy). */
128	  reply(status, body) {
129	    const copy = body === undefined ? undefined : JSON.parse(JSON.stringify(body));
130	    const json = () => (body === undefined
131	      ? Promise.reject(new SyntaxError('Unexpected end of JSON input'))
132	      : Promise.resolve(copy));
133	    this.resolveFetch(makeResponse(this.page, status, json));
134	  }
135	
136	  /** Reply whose body is not JSON: json() rejects. */
137	  replyNotJson(status) {
138	    this.resolveFetch(makeResponse(this.page, status, () => Promise.reject(new SyntaxError('bad json'))));
139	  }
140	
141	  /** Reply whose body arrives later: returns { send(body), fail() }. */
142	  replyLater(status) {
143	    let settle;
144	    const bodyPromise = new Promise((resolve, reject) => { settle = { resolve, reject }; });
145	    this.resolveFetch(makeResponse(this.page, status, () => bodyPromise));
146	    return {
147	      send: (body) => settle.resolve(JSON.parse(JSON.stringify(body))),
148	      fail: () => settle.reject(new TypeError('body stream failed')),
149	    };
150	  }
151	
152	  /** No reply at all (network error). */
153	  fail() {
154	    this.rejectFetch(new TypeError('Failed to fetch'));
155	  }
156	}
157	
158	class FakePage {
159	  constructor() {
160	    this.violations = [];
161	    this.log = [];
162	    this.fetches = [];
163	    this.proxies = new WeakMap();
164	    this.elements = new Map();
165	    for (const [id, tag, type] of PAGE_ELEMENTS) {
166	      this.elements.set(id, new FakeElement(this, tag, { id, type }));
167	    }
168	  }
169	
170	  el(id) {
171	    return this.elements.get(id);
172	  }
173	
174	  unwrap(proxy) {
175	    return this.proxies.get(proxy);
176	  }
177	
178	  /** Wraps a target so the script may use only `allowed` members; logs sets and calls. */
179	  wrap(target, label, allowed) {
180	    const page = this;
181	    const proxy = new Proxy(target, {
182	      get(t, prop) {
183	        if (typeof prop === 'symbol' || prop === 'then') return undefined;
184	        if (!allowed.has(prop)) return page.violate(`get ${label}.${prop}`);
185	        const value = t[prop];
186	        if (typeof value !== 'function') return value;
187	        return (...args) => {
188	          page.log.push(`${label}.${prop}()`);
189	          return value.apply(t, args);
190	        };
191	      },
192	      set(t, prop, value) {
193	        if (typeof prop === 'symbol' || !allowed.has(prop)) return page.violate(`set ${label}.${String(prop)}`);
194	        page.log.push(`${label}.${prop}=${JSON.stringify(value)}`);
195	        t[prop] = value;
196	        return true;
197	      },
198	      has: (t, prop) => allowed.has(prop),
199	      deleteProperty: (t, prop) => page.violate(`delete ${label}.${String(prop)}`),
200	      defineProperty: (t, prop) => page.violate(`define ${label}.${String(prop)}`),
201	    });
202	    this.proxies.set(proxy, target);
203	    return proxy;
204	  }
205	
