94	    return end === -1 ? text.length : end + 3;
95	  }
96	  if (text.startsWith('<!', pos) || text.startsWith('<?', pos)) {
97	    const end = text.indexOf('>', pos);
98	    return end === -1 ? text.length : end + 1;
99	  }
100	  if (text.startsWith('</', pos)) {
101	    const end = text.indexOf('>', pos);
102	    const name = text.slice(pos + 2, end === -1 ? text.length : end).trim().toLowerCase();
